import React, { useEffect, useState } from 'react';
// import { getBoxOffice } from '../api/movieApi'; // 실제 API 호출 함수
import MovieCard from '../components/MovieCard';

// 임시 데이터
const MOCK_MOVIES = [
  { id: 1, title: '영화 A', poster_path: 'https://via.placeholder.com/150' },
  { id: 2, title: '영화 B', poster_path: 'https://via.placeholder.com/150' },
  { id: 3, title: '영화 C', poster_path: 'https://via.placeholder.com/150' },
];

function HomePage() {
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchMovies = async () => {
      try {
        setLoading(true);
        // TODO: 실제 API 연동 시 아래 주석 해제
        // const response = await getBoxOffice();
        // setMovies(response.results);
        
        // 임시 데이터 사용
        setTimeout(() => {
          setMovies(MOCK_MOVIES);
          setLoading(false);
        }, 500);

      } catch (error) {
        console.error("영화 정보를 가져오는 데 실패했습니다.", error);
        setLoading(false);
      }
    };

    fetchMovies();
  }, []);

  if (loading) return <div>로딩 중...</div>;

  return (
    <div>
      <h1>박스오피스</h1>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '1rem' }}>
        {movies.map(movie => (
          <MovieCard key={movie.id} movie={movie} />
        ))}
      </div>
    </div>
  );
}

export default HomePage;
